arguments:
powershell -NoProfile -Command "$script = @'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes

function Redact([string]$s) {
  if (-not $s) { return '' }
  $s = [regex]::Replace($s, '\+\d[\d\s\-]{6,}', '[REDACTED_PHONE]')
  $s = [regex]::Replace($s, '@[A-Za-z0-9_]{4,}', '[REDACTED_HANDLE]')
  return $s
}

function Dump-Controls($root, [string]$label) {
  Write-Output \"=== $label ===\"
  $all = $root.FindAll([System.Windows.Automation.TreeScope]::Descendants, [System.Windows.Automation.Condition]::TrueCondition)
  $seen = New-Object System.Collections.Generic.HashSet[string]
  foreach ($el in $all) {
    $ct = $el.Current.ControlType.ProgrammaticName
    if ($ct -eq 'ControlType.ListItem' -or $ct -eq 'ControlType.DataItem') { continue }
    $name = Redact($el.Current.Name)
    if (-not $name -or $name.Length -gt 120) { continue }
    if ($ct -in @('ControlType.Button','ControlType.CheckBox','ControlType.RadioButton','ControlType.Edit','ControlType.ComboBox','ControlType.Slider','ControlType.TabItem','ControlType.Text','ControlType.MenuItem')) {
      $line = \"$ct | $name\"
      if ($seen.Add($line)) { Write-Output $line }
    }
  }
}

$p = Get-Process materialgram -ErrorAction SilentlyContinue | Select-Object -First 1
if (-not $p) { Write-Output 'ERROR: materialgram not running'; exit 1 }
$root = [System.Windows.Automation.AutomationElement]::RootElement.FindFirst(
  [System.Windows.Automation.TreeScope]::Children,
  (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ProcessIdProperty, $p.Id))
)
if (-not $root) { Write-Output 'ERROR: no UIA window'; exit 1 }

# Step 1: Click Go back until top-level Settings (My Account / Notifications and Sounds visible)
for ($i = 0; $i -lt 4; $i++) {
  $hasTop = $root.FindFirst([System.Windows.Automation.TreeScope]::Descendants, (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::NameProperty, 'Notifications and Sounds')))
  if ($hasTop) { break }
  $back = $root.FindFirst([System.Windows.Automation.TreeScope]::Descendants, (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::NameProperty, 'Go back')))
  if (-not $back) { break }
  $pat = $null
  if ($back.TryGetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern, [ref]$pat)) {
    $pat.Invoke()
    Start-Sleep -Milliseconds 600
  } else { break }
}

Dump-Controls $root 'TOP_LEVEL_SETTINGS'

# Step 2: Find and click Materialgram section if present
$btns = $root.FindAll([System.Windows.Automation.TreeScope]::Descendants, (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::Button)))
$mgBtn = $null
foreach ($b in $btns) {
  if ($b.Current.Name -match 'Materialgram|Material') {
    $mgBtn = $b
    break
  }
}
if ($mgBtn) {
  Write-Output (\"INVOKING: \" + $mgBtn.Current.Name)
  $pat = $null
  if ($mgBtn.TryGetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern, [ref]$pat)) {
    $pat.Invoke()
    Start-Sleep -Milliseconds 700
    Dump-Controls $root 'MATERIALGRAM_SECTION'
  }
} else {
  Write-Output 'MATERIALGRAM_BUTTON_NOT_FOUND_AT_TOP_LEVEL'
}
'@
Set-Content -Path C:\materialgram\uia_settings_sections.ps1 -Value $script -Encoding UTF8
Remove-Item C:\materialgram\uia_settings_sections.out -ErrorAction SilentlyContinue
schtasks /Create /F /TN REA_UIA_SETTINGS /SC ONCE /ST 00:00 /TR 'powershell -NoProfile -ExecutionPolicy Bypass -File C:\materialgram\uia_settings_sections.ps1 *> C:\materialgram\uia_settings_sections.out' /RU Admin /IT | Out-Null
schtasks /Run /TN REA_UIA_SETTINGS | Out-Null
Start-Sleep -Seconds 5
schtasks /Delete /F /TN REA_UIA_SETTINGS | Out-Null
if (Test-Path C:\materialgram\uia_settings_sections.out) { Get-Content C:\materialgram\uia_settings_sections.out } else { Write-Output 'NO_OUTPUT_FILE' }"

